SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s board evaluates a proposal to acquire a smaller, struggling competitor whose factory has excellent machinery/capacity but a poor compliance/labor-relations history. A director argues the acquisition price is attractive precisely BECAUSE of the target''s troubled reputation (depressing its market value). What HIDDEN cost, beyond the acquisition price itself, should the board weigh before approving?', '["No hidden cost exists; an attractively low acquisition price based on reputation discount is always a pure financial win with no offsetting cost consideration needed","The cost and time required to REMEDIATE the target''s compliance/labor issues post-acquisition (connecting to the earlier factory-safety and grievance-handling discussions) — poor labor relations and compliance history often reflect deeper, harder-to-fix cultural/systemic issues that don''t disappear simply through ownership change, and the acquiring group''s OWN reputation/buyer relationships could be damaged by association if these issues aren''t genuinely and visibly remediated, potentially offsetting or exceeding the acquisition price discount","Compliance and labor-relations history has no relationship to an acquisition''s true total cost or risk, making this entirely a separate, unrelated HR consideration disconnected from the financial acquisition decision","A troubled compliance history always automatically transfers to become an ASSET rather than a liability once acquired by a new, more reputable parent company, requiring zero remediation investment or risk consideration"]'::jsonb, 'The cost and time required to REMEDIATE the target''s compliance/labor issues post-acquisition (connecting to the earlier factory-safety and grievance-handling discussions) — poor labor relations and compliance history often reflect deeper, harder-to-fix cultural/systemic issues that don''t disappear simply through ownership change, and the acquiring group''s OWN reputation/buyer relationships could be damaged by association if these issues aren''t genuinely and visibly remediated, potentially offsetting or exceeding the acquisition price discount', 'This connects the earlier factory-safety/supply-chain-risk and grievance-handling discussions to a real M&A due-diligence consideration — an attractively discounted acquisition price for a troubled-reputation target isn''t a pure financial win if the underlying compliance/labor issues require significant, uncertain remediation investment (time, cost, cultural change management) AND risk damaging the ACQUIRING group''s own reputation with buyers by association during the remediation period — this hidden ''reputational and remediation cost'' must be weighed against the apparent price discount, since poor compliance culture often reflects deep, systemic issues that don''t automatically resolve simply through a change in ownership.', 3, '{"ma-hidden-compliance-cost"}'::text[]),
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile mill''s management applies ''scenario planning'' (modeling BEST-CASE, BASE-CASE, and WORST-CASE future demand scenarios) rather than relying on a SINGLE point-forecast for a major capacity expansion decision. What specific decision-making advantage does scenario planning offer over a single-number forecast, particularly for a LARGE, HARD-TO-REVERSE capital investment?', '["Scenario planning offers no advantage over a single-number forecast; both approaches provide mathematically identical decision-useful information for any capital investment decision","Scenario planning reveals how SENSITIVE the investment''s viability is to demand uncertainty — if the investment remains reasonably justified even under the WORST-CASE scenario, the decision is robust; but if it only makes sense under the BEST-CASE scenario, the investment carries much higher genuine risk than a single optimistic-leaning point forecast might suggest — this range-based view is especially valuable for LARGE, HARD-TO-REVERSE investments (like a new factory) where being wrong in the optimistic direction can be far more costly than for smaller, more easily adjustable decisions","A single point-forecast is always more decision-useful than scenario planning for any capital investment, regardless of the investment''s size or reversibility","Scenario planning is only useful for very SMALL investment decisions, providing zero additional value for large, strategic capacity expansion decisions specifically"]'::jsonb, 'Scenario planning reveals how SENSITIVE the investment''s viability is to demand uncertainty — if the investment remains reasonably justified even under the WORST-CASE scenario, the decision is robust; but if it only makes sense under the BEST-CASE scenario, the investment carries much higher genuine risk than a single optimistic-leaning point forecast might suggest — this range-based view is especially valuable for LARGE, HARD-TO-REVERSE investments (like a new factory) where being wrong in the optimistic direction can be far more costly than for smaller, more easily adjustable decisions', 'This connects to the earlier risk-assessment-alongside-ROI discussion — a single point-forecast hides how SENSITIVE an investment decision actually is to the underlying uncertainty; scenario planning explicitly reveals this by testing viability across a RANGE of plausible futures — an investment that remains reasonably justified even in the worst-case scenario is fundamentally more ROBUST (lower genuine risk) than one that only makes financial sense under best-case assumptions, even if both showed similar ''expected value'' under a single point-forecast — this range-based understanding is especially critical for large, hard-to-reverse investments (like a new factory, which can''t easily be ''undone'' if demand disappoints) where the DOWNSIDE scenario''s consequences matter disproportionately more than for smaller, more flexible/reversible decisions.', 3, '{"scenario-planning-capital-investment"}'::text[]),
('ddedfe3c-fe07-4167-b56f-656c9fb89f5e', 'advanced', 'multiple_choice', 'A textile group''s HR director proposes tying factory MANAGER bonuses partly to LONG-TERM operator retention rate (not just short-term production output/efficiency numbers). What UNINTENDED behavior does a bonus structure based PURELY on short-term output/efficiency risk encouraging, that a retention-inclusive structure would help counteract?', '["Short-term-output-only bonus structures have no possible unintended behavioral consequence, making this proposed change entirely unnecessary with zero underlying problem to solve","A manager incentivized PURELY on short-term output/efficiency might be tempted to push operators unsustainably hard (excessive overtime, minimal rest, harsh management style) to maximize THIS period''s numbers, even if this approach damages morale and drives higher operator turnover over time — since turnover''s real cost (recruitment, training, learning-curve efficiency drag, as established earlier) often shows up in LATER periods (potentially after that manager has already collected their bonus or moved roles), a purely short-term output metric can create a genuine incentive misalignment where a manager''s individually-rational bonus-maximizing behavior actually harms the factory''s longer-term interests","Including retention in manager bonus structures always REDUCES short-term output with no offsetting long-term benefit, making the HR director''s proposal a purely counterproductive idea","Operator turnover has no relationship to factory manager behavior or incentive structure, making this entire proposed bonus-structure change based on a nonexistent behavioral connection"]'::jsonb, 'A manager incentivized PURELY on short-term output/efficiency might be tempted to push operators unsustainably hard (excessive overtime, minimal rest, harsh management style) to maximize THIS period''s numbers, even if this approach damages morale and drives higher operator turnover over time — since turnover''s real cost (recruitment, training, learning-curve efficiency drag, as established earlier) often shows up in LATER periods (potentially after that manager has already collected their bonus or moved roles), a purely short-term output metric can create a genuine incentive misalignment where a manager''s individually-rational bonus-maximizing behavior actually harms the factory''s longer-term interests', 'This connects the earlier operator-turnover-cost and learning-curve discussions to a genuine INCENTIVE-DESIGN insight — a bonus structure based purely on short-term output/efficiency can create a classic principal-agent misalignment: a manager can rationally maximize THEIR bonus by pushing operators unsustainably hard now, even if this damages morale and drives turnover whose real cost (recruitment, training, efficiency-drag from the resulting learning-curve effect) materializes in LATER periods — possibly after that manager has already captured their bonus or moved to a different role — including a LONG-TERM metric like retention in the bonus structure helps realign the manager''s individual incentive with the factory''s genuine longer-term interest, a sophisticated application of incentive-design thinking to the earlier-established real costs of turnover.', 3, '{"incentive-design-retention"}'::text[]);
COMMIT;
